data.CSS:
:root { --ink:#12141a; --muted:#5b6470; --rule:#e6e8eb; --accent:#0b5fff; --sand:#f7f8fa; }
* { box-sizing:border-box; }
body { margin:0; color:var(--ink); background:#fff;
  font:16px/1.6 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; }
.shio-container { max-width:64rem; margin:0 auto; padding:0 1.5rem; }
.shio-stack > * + * { margin-top:1rem; }
.shio-nav { border-bottom:1px solid var(--rule); padding:1rem 0; }
.shio-nav ul { display:flex; gap:1.5rem; list-style:none; margin:0; padding:0; }
.shio-nav a { color:var(--ink); text-decoration:none; }
.shio-section { padding:4rem 0; }
.shio-section:nth-child(even) { background:var(--sand); }
.shio-heading { font-size:2rem; line-height:1.15; margin:0; }
.shio-subheading { font-size:1.25rem; color:var(--muted); margin:0; }
.shio-intro { font-size:1.125rem; color:var(--muted); }
.shio-grid { display:grid; gap:1.5rem; grid-template-columns:repeat(auto-fit,minmax(15rem,1fr));
  list-style:none; margin:0; padding:0; }
.shio-card { background:#fff; border:1px solid var(--rule); border-radius:.5rem; padding:1.25rem; }
.shio-card h3 { margin:0 0 .5rem; font-size:1.05rem; }
.shio-button { display:inline-block; background:var(--accent); color:#fff; text-decoration:none;
  padding:.7rem 1.25rem; border-radius:.375rem; font-weight:600; }
.shio-media img { max-width:100%; height:auto; }
footer { border-top:1px solid var(--rule); padding:2rem 0; color:var(--muted); }
